package com.axiom.application.analysis; import com.axiom.analysis.classification.ExplainableFailureClassifier; import java.util.*; import java.util.UUID; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class PipelineDiagnosisService {public static final String VERSION="axiom-classifier-v1";private final JdbcTemplate jdbc;private final ExplainableFailureClassifier classifier;public PipelineDiagnosisService(JdbcTemplate j,ExplainableFailureClassifier c){jdbc=j;classifier=c;}@Transactional public Map<String,Object> diagnose(UUID run){var events=jdbc.queryForList("select id,fingerprint,exception_type,normalized_message from failure_events where pipeline_run_id=?",run);if(events.isEmpty())throw new IllegalArgumentException("Pipeline run has no extracted failure events.");int unknown=0;Map<String,Integer> breakdown=new TreeMap<>();for(var e:events){UUID event=(UUID)e.get("id");var r=classifier.classify((String)e.get("normalized_message"),(String)e.get("exception_type"));if(r.classification().name().equals("UNKNOWN"))unknown++;breakdown.merge(r.classification().name(),1,Integer::sum);UUID id=UUID.randomUUID();jdbc.update("insert into failure_diagnoses(id,pipeline_run_id,failure_event_id,fingerprint,classification,confidence,confidence_level,summary,probable_cause,recommended_action,classifier_version) values (?,?,?,?,?,?,?,?,?,?,?) on conflict(failure_event_id,classifier_version) do update set classification=excluded.classification,confidence=excluded.confidence,confidence_level=excluded.confidence_level,summary=excluded.summary",id,run,event,e.get("fingerprint"),r.classification().name(),r.confidence(),r.level().name(),summary(r.classification()),"Evidence indicates "+r.classification().name().toLowerCase().replace('_',' ')+".","Inspect the supporting failure event and surrounding CI service logs.",VERSION);UUID diagnosis=jdbc.query("select id from failure_diagnoses where failure_event_id=? and classifier_version=?",rs->{rs.next();return(UUID)rs.getObject(1);},event,VERSION);jdbc.update("delete from diagnosis_evidence where diagnosis_id=?",diagnosis);for(var x:r.evidence())jdbc.update("insert into diagnosis_evidence(id,diagnosis_id,code,category,severity,priority,weight,description,rule_id) values (?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),diagnosis,x.code(),x.category().name(),x.severity().name(),x.priority().name(),x.weight(),x.description(),x.ruleId());}return Map.of("pipelineRunId",run,"failureCount",events.size(),"diagnosisCount",events.size(),"unknownCount",unknown,"classifierVersion",VERSION,"classificationBreakdown",breakdown);}private String summary(com.axiom.domain.failure.FailureClassification c){return switch(c){case TEST_FAILURE->"A test assertion failed.";case DEPENDENCY_FAILURE->"A required dependency could not be resolved.";case INFRASTRUCTURE_FAILURE->"Required CI infrastructure appears unavailable.";case RESOURCE_EXHAUSTION->"CI execution appears constrained by an exhausted resource.";case UNKNOWN->"Axiom could not determine a reliable failure category.";default->"Evidence indicates a "+c.name().toLowerCase().replace('_',' ')+" failure.";};}}
